  console.log((ok ? 'PASS' : 'FAIL') + ' ' + name);
  if (!ok) { fail++; console.log('  got:  ' + JSON.stringify(got)); console.log('  want: ' + JSON.stringify(want)); }
};
// spec example: data = x"y<LF>z  -> python json.dumps gives x\"y\nz (one backslash before n)
